function evidence = f90_xtherm03_extract_reference_evidence( ...
    modelPath, officialScenarios, outDir)
% Public relocation of the current MSF reference evidence extractor.
arguments
    modelPath (1,1) string
    officialScenarios (1,1) string
    outDir (1,1) string
end
assert(isfile(modelPath), "SimuVerity:F90:XTHERM03:ModelMissing", ...
    "Reference model not found: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XTHERM03:ScenariosMissing", ...
    "Official scenario contract not found: %s", officialScenarios);
official = jsondecode(fileread(officialScenarios));
assert(string(official.task_id) == "F90-XTHERM-03" && ...
    isfield(official, "scenarios") && numel(official.scenarios) == 6 && ...
    isfield(official, "simulation") && ...
    double(official.simulation.stop_time_s) == 300, ...
    "SimuVerity:F90:XTHERM03:ScenarioBinding", ...
    "Exact F90-XTHERM-03 official scenarios are required.");
assert(strcmpi(localFilePresence(modelPath), ...
    "present"), ...
    "SimuVerity:F90:XTHERM03:ModelBinding", "Pinned reference-model binding mismatch.");
assert(~isfolder(outDir), "SimuVerity:F90:XTHERM03:OutputExists", ...
    "Fresh evidence output already exists: %s", outDir);
mkdir(outDir);
sourceRoot = fileparts(modelPath);
scenarios = official.scenarios;

evidence = struct( ...
    "schema", "simuverity.formal90-fixed-evidence.v1", ...
    "task_id", "F90-XTHERM-03", ...
    "evaluation_subject", "reference", ...
    "matlab_release", version("-release"), ...
    "started_at", localNow, "finished_at", "", ...
    "source_model", string(modelPath), ...
    "source_model_file_presence", localFilePresence(modelPath), ...
    "load_pass", false, "update_pass", false, ...
    "compile_pass", false, "evidence_complete", false, ...
    "static_audit", struct, "scenarios", [], "errors", struct);

originalDir = pwd;
originalPath = path;
cleanup = onCleanup(@() localRestore(originalDir, originalPath)); %#ok<NASGU>
try
    cd(sourceRoot);
    addpath(sourceRoot, "-begin");
    load_system(modelPath);
    model = "MSFcascade";
    evidence.load_pass = true;
    set_param(model, "StopFcn", "");
    set_param(model + "/Enable" + newline + ...
        "0: Simulink" + newline + "1:     HIL     ", "Value", "0");
    localInstallTaps(model);
    evidence.static_audit = localStaticAudit(model, sourceRoot);
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;

    rows = repmat(localEmptyScenario, numel(scenarios), 1);
    for k = 1:numel(scenarios)
        rows(k).id = string(scenarios(k).id);
        rows(k).requested_inputs = scenarios(k);
        try
            localApplyScenario(model, scenarios(k));
            set_param(model, "SimulationCommand", "update");
            simIn = Simulink.SimulationInput(model);
            simIn = simIn.setModelParameter( ...
                "StopTime", sprintf("%.17g", official.simulation.stop_time_s), ...
                "ReturnWorkspaceOutputs", "on");
            started = tic;
            evalc("simOut = sim(simIn);");
            rows(k).simulation_wall_clock_s = toc(started);
            rows(k).outputs = localExtractOutputs(simOut, scenarios(k));
            rows(k).metrics = localMetrics(rows(k).outputs, scenarios(k));
            rows(k).simulation_pass = true;
            rows(k).required_evidence_pass = localOutputsValid( ...
                rows(k).outputs, official.simulation.stop_time_s);
            rows(k).valid = rows(k).required_evidence_pass;
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
    evidence.evidence_complete = evidence.load_pass && evidence.update_pass && ...
        evidence.compile_pass && all([rows.valid]) && ...
        strcmpi(evidence.source_model_file_presence, localFilePresence(modelPath));
catch ME
    evidence.errors.session = localError(ME);
end
evidence.finished_at = localNow;
localCloseAll;
localWriteJson(fullfile(outDir, "evidence.json"), evidence);
fprintf("F90_XTHERM03_EVIDENCE complete=%d valid=%d/%d path=%s\n", ...
    evidence.evidence_complete, localValidCount(evidence.scenarios), ...
    numel(evidence.scenarios), fullfile(outDir, "evidence.json"));
end

function localInstallTaps(model)
plant = model + "/Multi Stage Flash Desalination";
names = ["f90_lb22", "f90_tb22", "f90_tb0", "f90_ld22", ...
    "f90_blowdown", "f90_distillate"];
for k = 1:numel(names)
    localTap(model, plant, names(k), k);
end
localTap(model, model + "/Sum", "f90_recycle", 1);
localTap(model, model + "/Sum1", "f90_feed_temperature", 1);
localTap(model, model + "/Saturation", "f90_steam", 1);
end

function localTap(parent, source, variable, portIndex)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, "SimuVerity:F90:XTHERM03:TapCollision", ...
    "Temporary tap already exists: %s", tap);
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(numel(sourcePorts.Outport) >= portIndex && sourcePorts.Outport(portIndex) > 0, ...
    "SimuVerity:F90:XTHERM03:TapPort", "Missing source port %d on %s", portIndex, source);
add_line(parent, sourcePorts.Outport(portIndex), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, scenario)
set_param(model + "/Bo, (ton//min)", "Value", ...
    sprintf("%.17g", scenario.recycle_brine_flow_ton_per_min));
set_param(model + "/Tf, (C)", "Value", ...
    sprintf("%.17g", scenario.feed_temperature_C));
set_param(model + "/Ws,  (kg//min)", "Value", ...
    sprintf("%.17g", scenario.steam_feed_kg_per_min));
set_param(model + "/Initial setpoint", "Value", ...
    sprintf("%.17g", scenario.top_brine_temperature_setpoint_C));
set_param(model + "/Setpoint Wd", "Value", ...
    sprintf("%.17g", scenario.distillate_flow_setpoint_ton_per_min));
set_param(model + "/Step on Tf", "Time", ...
    sprintf("%.17g", scenario.disturbance_start_s), ...
    "Before", "0", "After", sprintf("%.17g", scenario.feed_temperature_step_C));
set_param(model + "/Step on B0", "Time", ...
    sprintf("%.17g", scenario.disturbance_start_s), ...
    "Before", "0", "After", ...
    sprintf("%.17g", scenario.recycle_flow_step_ton_per_min));
end

function outputs = localExtractOutputs(simOut, scenario)
lb22 = localSeries(simOut, "f90_lb22");
tb22 = localSeries(simOut, "f90_tb22");
tb0 = localSeries(simOut, "f90_tb0");
ld22 = localSeries(simOut, "f90_ld22");
blowdown = localSeries(simOut, "f90_blowdown");
distillate = localSeries(simOut, "f90_distillate");
recycle = localSeries(simOut, "f90_recycle");
feedTemperature = localSeries(simOut, "f90_feed_temperature");
steam = localSeries(simOut, "f90_steam");
series = {lb22, tb22, tb0, ld22, blowdown, distillate, recycle, ...
    feedTemperature, steam};
startTime = max(cellfun(@(x) x.time(1), series));
endTime = min(cellfun(@(x) x.time(end), series));
assert(endTime > startTime, "SimuVerity:F90:XTHERM03:Overlap", ...
    "Required reference signals have no common time interval.");
time = linspace(startTime, endTime, 1501)';
plantState = [localInterp(lb22, time), localInterp(tb22, time), ...
    localInterp(tb0, time), localInterp(ld22, time)];
flowState = [localInterp(blowdown, time), localInterp(distillate, time), ...
    localInterp(recycle, time), localInterp(steam, time)];
temperatureSetpoint = scenario.top_brine_temperature_setpoint_C .* ones(size(time));
flowSetpoint = scenario.distillate_flow_setpoint_ton_per_min .* ones(size(time));
controlState = [temperatureSetpoint, flowSetpoint, ...
    temperatureSetpoint - plantState(:,3), flowSetpoint - flowState(:,2)];
outputs = struct("time_s", time, "plant_state", plantState, ...
    "flow_state", flowState, "control_state", controlState, ...
    "feed_temperature_C", localInterp(feedTemperature, time));
end

function metrics = localMetrics(outputs, scenario)
t = outputs.time_s;
plant = outputs.plant_state;
flow = outputs.flow_state;
control = outputs.control_state;
tail = t >= max(t(1), t(end) - 0.2 * (t(end) - t(1)));
pre = t < scenario.disturbance_start_s & ...
    t >= max(t(1), scenario.disturbance_start_s - 30);
post = t >= scenario.disturbance_start_s;
if ~any(pre), pre = t <= t(1) + 0.2 * (t(end) - t(1)); end
metrics = struct( ...
    "top_brine_tail_mae_C", median(abs(control(tail,3))), ...
    "distillate_tail_mae_ton_per_min", median(abs(control(tail,4))), ...
    "top_brine_peak_error_C", max(abs(control(post,3))), ...
    "distillate_peak_error_ton_per_min", max(abs(control(post,4))), ...
    "last_brine_level_min_m", min(plant(:,1)), ...
    "last_brine_level_max_m", max(plant(:,1)), ...
    "last_distillate_level_min_m", min(plant(:,4)), ...
    "last_distillate_level_max_m", max(plant(:,4)), ...
    "top_brine_temperature_span_C", max(plant(:,3)) - min(plant(:,3)), ...
    "distillate_flow_span_ton_per_min", max(flow(:,2)) - min(flow(:,2)), ...
    "steam_flow_span_kg_per_min", max(flow(:,4)) - min(flow(:,4)), ...
    "pre_top_brine_temperature_C", median(plant(pre,3)), ...
    "tail_top_brine_temperature_C", median(plant(tail,3)), ...
    "pre_distillate_flow_ton_per_min", median(flow(pre,2)), ...
    "tail_distillate_flow_ton_per_min", median(flow(tail,2)), ...
    "all_finite", all(isfinite([plant(:); flow(:); control(:)])));
end

function pass = localOutputsValid(outputs, stopTime)
t = outputs.time_s;
pass = numel(t) >= 100 && all(isfinite(t)) && all(diff(t) > 0) && ...
    t(1) <= 1e-9 && t(end) >= stopTime - 0.2 && ...
    isequal(size(outputs.plant_state), [numel(t), 4]) && ...
    isequal(size(outputs.flow_state), [numel(t), 4]) && ...
    isequal(size(outputs.control_state), [numel(t), 4]) && ...
    all(isfinite([outputs.plant_state(:); outputs.flow_state(:); ...
    outputs.control_state(:)]));
end

function audit = localStaticAudit(model, sourceRoot)
plant = model + "/Multi Stage Flash Desalination";
controllers = find_system(model, "FollowLinks", "off", ...
    "LookUnderMasks", "all", "MaskType", "PID Controller");
plantPorts = get_param(plant, "PortHandles");
audit = struct( ...
    "published_stage_count", 22, ...
    "plant_input_port_count", numel(plantPorts.Inport), ...
    "plant_output_port_count", numel(plantPorts.Outport), ...
    "feedback_controller_count", numel(controllers), ...
    "native_msf_sfunction", string(get_param( ...
        plant + "/Open loop", "FunctionName")), ...
    "simulink_path_selected", strcmp(get_param(model + "/Enable" + newline + ...
        "0: Simulink" + newline + "1:     HIL     ", "Value"), "0"), ...
    "source_dependencies_complete", all(isfile(fullfile(sourceRoot, ...
        ["MSFprocess.m", "msfplant.m", "PRESS.m", "LATENT.m", "x68.inc"]))), ...
    "temperature_feedback_connected", localInputsConnected( ...
        model + "/Simulink/PID controller" + newline + "for TB0"), ...
    "distillate_feedback_connected", localInputsConnected( ...
        model + "/Simulink/PID controller" + newline + "for Wd"));
end

function pass = localInputsConnected(block)
ports = get_param(block, "PortHandles");
pass = numel(ports.Inport) >= 2;
for port = ports.Inport(:)'
    line = get_param(port, "Line");
    pass = pass && line > 0 && get_param(line, "SrcPortHandle") > 0;
end
end

function series = localSeries(simOut, name)
try, value = simOut.get(name); catch, value = []; end
if isempty(value) && evalin("base", sprintf("exist('%s','var')", name))
    value = evalin("base", name);
end
assert(isa(value, "timeseries"), "SimuVerity:F90:XTHERM03:MissingSignal", ...
    "Required Timeseries %s is missing.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data,1) ~= numel(time) && size(data,2) == numel(time), data = data.'; end
assert(size(data,1) == numel(time) && size(data,2) == 1, ...
    "SimuVerity:F90:XTHERM03:SignalShape", "Unexpected shape for %s.", name);
[time, index] = unique(time, "stable");
data = data(index,:);
assert(numel(time) >= 2 && all(isfinite(time)) && all(isfinite(data)), ...
    "SimuVerity:F90:XTHERM03:SignalInvalid", "Invalid signal %s.", name);
series = struct("time", time, "values", data);
end

function values = localInterp(series, time)
values = interp1(series.time, series.values, time, "linear", "extrap");
values = values(:);
end

function row = localEmptyScenario
row = struct("id", "", "requested_inputs", struct, ...
    "simulation_wall_clock_s", NaN, "simulation_pass", false, ...
    "required_evidence_pass", false, "valid", false, ...
    "outputs", struct, "metrics", struct, "error", struct);
end

function count = localValidCount(rows)
if isempty(rows)
    count = 0;
else
    count = sum([rows.valid]);
end
end

function localRestore(originalDir, originalPath)
localCloseAll;
try, cd(originalDir); catch, end
try, path(originalPath); catch, end
end

function localCloseAll
models = string(find_system("type", "block_diagram"));
for model = models(:)'
    try, close_system(model, 0); catch, end
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function value = localNow
value = string(datetime("now", "TimeZone", "UTC", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
end

function value = localError(ME)
value = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message), ...
    "report", string(getReport(ME, "extended", "hyperlinks", "off")));
end

function localWriteJson(path, value)
text = jsonencode(value, "PrettyPrint", true);
fid = fopen(path, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XTHERM03:Write", "Cannot write %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", text);
end
